playground.css:
body { font-family: system-ui, sans-serif; padding: 14px; background: #f8fafc; color: #0f172a; }
.scroll-area {
  height: 240px;
  overflow-y: auto;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  background: #fff;
}
.sticky-bar {
  position: sticky;
  top: 0;
  z-index: 10;
  padding: 10px 14px;
  background: #0f172a;
  color: #fff;
  font-size: 0.84rem;
  font-weight: 600;
}
.card {
  position: relative;
  margin: 18px 14px;
  padding: 16px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  background: #f8fafc;
}
.badge {
  position: absolute;
  top: -10px;
  right: 12px;
  padding: 3px 8px;
  border-radius: 999px;
  background: #2563eb;
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
}
h3 { margin: 0 0 6px; font-size: 0.96rem; }
p { margin: 0; font-size: 0.84rem; color: #475569; }
.spacer { height: 240px; padding: 14px; color: #94a3b8; font-size: 0.85rem; }
